config.command:
set -euo pipefail
SINCE="{{ since }}"
SINCE=${SINCE:-24 hours ago}
BRANCH="{{ branch }}"
BRANCH=${BRANCH:-HEAD}
MAX={{ max_commits }}
MAX=${MAX:-50}
echo "=== Git Activity since: $SINCE ==="
echo "Branch: $BRANCH"
echo ""
git log "$BRANCH" --since="$SINCE" --pretty=format:"%an|%s|%h|%ar" --no-merges -n "$MAX" 2>/dev/null | awk -F'|' '
{
  author=$1; msg=$2; hash=$3; when=$4
  commits[author] = commits[author] "|" msg " (" hash ", " when ")"
  count[author]++
}
END {
  for (a in commits) {
    print "\n### " a " (" count[a] " commits)"
    n=split(commits[a], items, "|")
    for (i=2; i<=n; i++) print "- " items[i]
  }
}' || echo "No commits found in the given time range."
echo ""
echo "--- Changed Files ---"
git diff --name-only HEAD~5 HEAD 2>/dev/null | sort -u | head -20 || true
echo "=== Git Activity Complete ==="
